  const act=aS/9, inh=iS/9, harm=hS/9;
  const bg = (Math.sin(sx2*0.04+sy2*0.025+t*0.8)+Math.sin(sx2*0.03-sy2*0.04+t*1.1))/2 + Math.sin((sx2+sy2)*0.12+t*2.5)*0.2 + Math.sin((sx2-sy2)*0.1-t*2)*0.2 + Math.sin(sx2*0.08+t*1.8)*Math.cos(sy2*0.06-t*1.3)*0.3;
